insert into fitness.lift_modes (plan_version, mode, description) values
  ('v2', 'full', 'As written in Hevy.'),
  ('v2', 'reduced', 'Same exercises. Keep the top set on RDL, bench, incline, pull-up and row at full load; drop one set from everything else; stop 2 reps short. Down weeks, re-entry and race weeks.'),
  ('v2', 'heavy', 'Same exercises. Mon: RDL 3 x 3-5, bench 3 x 5, barbell row 3 x 6, heavy step-up 3 x 5 per side, lunges 2 x 20 m; accessories as written. Wed: weighted pull-ups 4 x 4-6 + dips, incline 3 x 5-6; arms, laterals and the rest as written. Weeks 28-39.'),
  ('v2', 'short', 'Full Body #3 minus hip abduction/adduction and minus one set from every other exercise (about 45 min). Chest fly, hammer curl, laterals, pull-ups and row stay. Used once the long run passes about 2.5 h.'),
  ('v2', 'taper', 'Same exercises, about half the sets, one heavy top set per main lift. No lower-body loading in race week.'),
  ('v2', 'upper', 'Full Body #1 without RDL, step-ups, lunges and step-downs (day after the marathon).'),
  ('v2', 'hotel', 'USA: whatever the hotel gym has. Pull-ups or hangs, push-ups or dumbbell press, rows, curls, laterals, split squats, calf and tibialis raises, Copenhagen plank. Maintain, don''t progress.'),
  ('v2', 'optional', 'Only if fresh.'),
  ('v2', 'none', 'No lift.')
